![medium](https://www.gstatic.com/codereviewagent/medium-priority.svg)

The test description states that it verifies behavior when input files are 'missing or malformed', but the implementation only tests the missing files scenario. To fully satisfy the test description and adhere to the repository's guidelines on fail-closed regression testing, we should also add a test case that writes a malformed JSON file and asserts that `input_artifact_malformed` diagnostics are recorded and validation fails closed.

```javascript
  test('validator fails closed and records diagnostics when input files are missing', async () => {
    const {
      buildRagLiteHvyCopilotRagPilotFixtures,
    } = await import('../build-rag-lite-hvy-copilot-rag-pilot-fixtures.mjs');

    const tempRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'rag-lite-hvy-05-fail-closed-'));
    try {
      const result = buildRagLiteHvyCopilotRagPilotFixtures({
        root: tempRoot,
        generatedAt: '2026-07-06T00:00:00.000Z',
      });

      expect(result.validatorResult.validator_status).toBe('fail');
      expect(result.validatorResult.errors.some((error) => (
        error.startsWith('input_artifact_missing:')
      ))).toBe(true);
      expect(result.validatorResult.checks.find((check) => (
        check.id === 'upstream_validators_pass'
      )).status).toBe('fail');
    } finally {
      fs.rmSync(tempRoot, { recursive: true, force: true });
    }
  });

  test('validator fails closed and records diagnostics when input files are malformed', async () => {
    const {
      DEFAULT_PATHS,
      buildRagLiteHvyCopilotRagPilotFixtures,
    } = await import('../build-rag-lite-hvy-copilot-rag-pilot-fixtures.mjs');

    const tempRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'rag-lite-hvy-05-malformed-'));
    try {
      const malformedPath = path.join(tempRoot, DEFAULT_PATHS.retrievalPacketsIn);
      fs.mkdirSync(path.dirname(malformedPath), { recursive: true });
      fs.writeFileSync(malformedPath, '{ invalid json }', 'utf8');

      const result = buildRagLiteHvyCopilotRagPilotFixtures({
        root: tempRoot,
        generatedAt: '2026-07-06T00:00:00.000Z',
      });

      expect(result.validatorResult.validator_status).toBe('fail');
      expect(result.validatorResult.errors.some((error) => (
        error.startsWith('input_artifact_malformed:')
      ))).toBe(true);
    } finally {
      fs.rmSync(tempRoot, { recursive: true, force: true });
    }
  });
```

